//! Types shared by the server, the MCP tools and the web page.
//!
//! Every type here is exported to TypeScript (see `web/src/gen`) so the two
//! sides can't drift. Line numbers are 1-based unless a field says otherwise;
//! column offsets are UTF-16 code units, the unit JavaScript strings use.

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use utoipa::ToSchema;

macro_rules! id_type {
    ($(#[$doc:meta])* $name:ident) => {
        $(#[$doc])*
        #[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema, ToSchema)]
        #[serde(transparent)]
        pub struct $name(pub String);

        impl std::fmt::Display for $name {
            fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                f.write_str(&self.0)
            }
        }

        impl From<&str> for $name {
            fn from(s: &str) -> Self {
                Self(s.to_owned())
            }
        }
    };
}

id_type!(
    /// A review: one shared diff and its conversation.
    ReviewId
);
id_type!(
    /// A thread of messages anchored to lines, or an agent note.
    ThreadId
);
id_type!(
    /// One message in a thread or in the chat.
    MessageId
);

/// Revisions count up from 1 each time the diff is rebuilt with new content.
pub type Revision = u32;

/// Milliseconds since the Unix epoch.
pub type Millis = u64;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema, ToSchema)]
#[serde(rename_all = "lowercase")]
pub enum Side {
    Old,
    New,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "lowercase")]
pub enum FileStatus {
    Added,
    Deleted,
    Modified,
    Renamed,
    /// Not part of the diff: a file opened for context.
    Unchanged,
}

/// Everything the page needs to render one revision of a review.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Snapshot {
    pub revision: Revision,
    pub files: Vec<FileDiff>,
    pub symbols: Vec<Symbol>,
}

/// One file's diff: both sides in full, aligned line by line.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct FileDiff {
    pub path: String,
    pub old_path: Option<String>,
    pub status: FileStatus,
    /// Display name of the language, when we recognise it.
    pub language: Option<String>,
    /// Why the contents aren't shown, when they aren't.
    #[serde(default)]
    pub omitted: Option<Omitted>,
    /// Changes the rows can't show: the file mode, line endings, the final
    /// newline, a submodule's commit. Short phrases, e.g. "mode 100644 → 100755".
    #[serde(default)]
    pub details: Vec<String>,
    /// Why the file starts collapsed (set by the agent, e.g. "generated by ts-rs").
    pub collapsed: Option<String>,
    /// What kind of file it is, as diffd can tell by itself: `test`, `generated`.
    #[serde(default)]
    pub labels: Vec<String>,
    pub added: u32,
    pub removed: u32,
    pub old: Option<SideText>,
    pub new: Option<SideText>,
    /// The whole file, aligned: (old line index, new line index), 0-based.
    pub rows: Vec<Row>,
    /// New-side lines (1-based) that changed since the previous revision.
    pub since: Vec<u32>,
}

/// Why a file's contents aren't shown.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub enum Omitted {
    Binary,
    /// Over the size limit: listed, never read.
    TooLarge,
    /// A submodule: a commit, not a file.
    Submodule,
}

impl std::fmt::Display for Omitted {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(match self {
            Self::Binary => "a binary file",
            Self::TooLarge => "too large to show",
            Self::Submodule => "a submodule",
        })
    }
}

/// One side of a file.
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct SideText {
    pub lines: Vec<String>,
    /// Per line, flattened `[start, end, class, start, end, class, …]`.
    /// `class` indexes [`SyntaxClass::ALL`].
    pub syntax: Vec<Vec<u32>>,
    /// Per line, flattened `[start, end, …]`: tokens difftastic marks as novel.
    pub novel: Vec<Vec<u32>>,
}

/// An aligned pair of 0-based line indices; `None` where one side has no line.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
pub struct Row(pub Option<u32>, pub Option<u32>);

/// Highlight classes, in the order their indices are sent over the wire.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum SyntaxClass {
    Keyword,
    String,
    Comment,
    Constant,
    Number,
    Function,
    Type,
    Variable,
    Property,
    Attribute,
    Tag,
    Operator,
    Punctuation,
    Module,
    Escape,
    Heading,
    Link,
}

impl SyntaxClass {
    pub const ALL: [SyntaxClass; 17] = [
        Self::Keyword,
        Self::String,
        Self::Comment,
        Self::Constant,
        Self::Number,
        Self::Function,
        Self::Type,
        Self::Variable,
        Self::Property,
        Self::Attribute,
        Self::Tag,
        Self::Operator,
        Self::Punctuation,
        Self::Module,
        Self::Escape,
        Self::Heading,
        Self::Link,
    ];

    pub fn name(self) -> &'static str {
        match self {
            Self::Keyword => "keyword",
            Self::String => "string",
            Self::Comment => "comment",
            Self::Constant => "constant",
            Self::Number => "number",
            Self::Function => "function",
            Self::Type => "type",
            Self::Variable => "variable",
            Self::Property => "property",
            Self::Attribute => "attribute",
            Self::Tag => "tag",
            Self::Operator => "operator",
            Self::Punctuation => "punctuation",
            Self::Module => "module",
            Self::Escape => "escape",
            Self::Heading => "heading",
            Self::Link => "link",
        }
    }
}

/// A definition found by the tags queries: what `gd` jumps to.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Symbol {
    pub name: String,
    /// e.g. "function", "class", "method", "module".
    pub kind: String,
    /// Index into [`Snapshot::files`].
    pub file: u32,
    pub side: Side,
    pub line: u32,
    pub start: u32,
    pub end: u32,
    /// The whole definition's first and last line (1-based), e.g. a function with its body.
    #[schema(min_items = 2, max_items = 2)]
    pub lines: [u32; 2],
}

// ---------------------------------------------------------------------------
// Conversation
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema, ToSchema)]
#[serde(rename_all = "lowercase")]
pub enum Author {
    User,
    Agent,
}

/// Where a thread lives: a line range on one side of a file.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Anchor {
    pub path: String,
    pub side: Side,
    pub start: u32,
    pub end: u32,
    /// The exact anchored text, used to follow the lines across revisions.
    pub text: String,
    /// Set when the comment was written while looking at part of the review's
    /// history (one commit, or a few) rather than the whole diff.
    #[serde(default)]
    pub range: Option<CommitRange>,
}

/// Two points in a review's history: commits, or the working tree for `to: null`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct CommitRange {
    pub from: String,
    pub to: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema, ToSchema)]
#[serde(rename_all = "lowercase")]
pub enum NoteKind {
    Explain,
    Why,
    Risk,
    Question,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum ThreadKind {
    /// Started by the user on a selection.
    Comment,
    /// An annotation the agent wrote when sharing; `order` is its place in the tour.
    Note { kind: NoteKind, order: u32 },
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Thread {
    pub id: ThreadId,
    pub kind: ThreadKind,
    pub anchor: Anchor,
    pub resolved: bool,
    /// The anchored code changed after the thread started, in this revision.
    pub changed_in: Option<Revision>,
    /// The anchored code can no longer be found.
    pub outdated: bool,
    pub messages: Vec<Message>,
    pub created_at: Millis,
}

/// A message in a thread, or in the chat.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Message {
    pub id: MessageId,
    pub author: Author,
    /// Markdown.
    pub body: String,
    pub created_at: Millis,
    /// When the agent received it (user messages only).
    pub delivered_at: Option<Millis>,
}

/// How the agent arranged the review for reading: who it is, related changes
/// grouped together, and labels the user can hide files by.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Layout {
    /// The agent's name as its harness gives it, e.g. "Claude" or "Codex".
    #[serde(default)]
    pub agent: Option<String>,
    #[serde(default)]
    pub groups: Vec<Group>,
    #[serde(default)]
    pub labels: Vec<Label>,
}

/// A chapter of the agent's guided tour: files that change together for one
/// reason, read one after another.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema, ToSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Group {
    /// What these changes are, in a few words, e.g. "The rate limiter API" or "Database migrations".
    pub title: String,
    /// One or two plain sentences on what changed here and why, shown above the chapter's code and in the
    /// tour's sidebar. `path:line` references to the spots that matter become links.
    #[serde(default)]
    pub summary: Option<String>,
    /// Files in the diff, as paths, directories or globs (`web/src/**`, `*.sql`), in reading order.
    pub files: Vec<String>,
}

/// A label on some files (e.g. `frontend`), which the user can hide.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema, ToSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Label {
    /// Short and lowercase, e.g. `frontend`, `backend`, `docs`, `generated`, `test`.
    pub name: String,
    /// Paths, directories or globs, e.g. `web/**` or `*.sqlx`.
    pub files: Vec<String>,
}

/// A range the agent labelled when sharing: tests, or code folded behind a summary.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Region {
    pub path: String,
    pub side: Side,
    /// 1-based inclusive line range; `None` means the whole file.
    #[schema(min_items = 2, max_items = 2)]
    pub lines: Option<[u32; 2]>,
    pub kind: RegionKind,
    /// For folds: what changed in there, in plain language.
    pub summary: Option<String>,
    /// The anchored text, used to follow the lines across revisions.
    #[serde(default)]
    pub text: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema, ToSchema)]
#[serde(rename_all = "lowercase")]
pub enum RegionKind {
    /// Test code: marked with a line along its side.
    Test,
    /// Folded by default behind `summary`.
    Fold,
}

/// What the agent is doing, as far as the page can tell.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "lowercase")]
pub enum Presence {
    /// Blocked in `wait_for_feedback`: comments reach it right away.
    Listening,
    /// Connected but busy; comments wait for its next check.
    Working,
    /// No agent has checked in recently.
    Away,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct ShowRequest {
    pub path: String,
    pub side: Side,
    pub start: u32,
    pub end: u32,
    pub message: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "lowercase")]
pub enum ReviewStatus {
    Open,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct ReviewMeta {
    pub id: ReviewId,
    pub title: String,
    pub summary: Option<String>,
    pub repo_path: String,
    pub repo_name: String,
    pub from: String,
    /// `None` means the working tree.
    pub to: Option<String>,
    pub revision: Revision,
    pub status: ReviewStatus,
    pub created_at: Millis,
    pub updated_at: Millis,
}

/// How bad a language server's diagnostic is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "lowercase")]
pub enum Severity {
    Error,
    Warning,
    Info,
    Hint,
}

/// A language server's error or warning on the new side of a file.
/// Lines are 1-based; columns count UTF-16 code units from 0, as in the page.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Diagnostic {
    pub line: u32,
    pub col: u32,
    pub end_line: u32,
    pub end_col: u32,
    pub severity: Severity,
    pub message: String,
    /// The tool that reported it, e.g. `rustc`, `pyright`.
    pub source: Option<String>,
}

/// What the page can ask a language server about a position.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub enum CodeQuery {
    Definition,
    TypeDefinition,
    Hover,
    /// Every use of the symbol, its declaration included.
    References,
}

/// Where a language server points: a file in the repository (a relative
/// path), or outside it (an absolute path, e.g. a library's source).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct CodeLocation {
    pub path: String,
    pub external: bool,
    /// 1-based.
    pub line: u32,
    pub col: u32,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum CodeAnswer {
    Locations {
        locations: Vec<CodeLocation>,
    },
    /// Markdown, as the server wrote it.
    Hover {
        markdown: String,
    },
    /// No language server for this file (or it couldn't answer): fall back to what the page knows.
    Unavailable {
        reason: String,
    },
}

/// A language server running for the review's files, for the status line.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct LanguageServerStatus {
    /// Its name in the config, e.g. `rust-analyzer`.
    pub name: String,
    pub state: LanguageServerState,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum LanguageServerState {
    Starting,
    /// Working on something it reports (`$/progress`): loading the workspace, indexing, checking.
    Busy {
        title: String,
        message: Option<String>,
        percentage: Option<u32>,
    },
    Ready,
    /// Not installed, or it kept crashing.
    Unavailable {
        reason: String,
    },
}

/// A commit between the review's two sides.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Commit {
    pub sha: String,
    pub short: String,
    pub subject: String,
    pub author: String,
    pub time: Millis,
}

/// The commits a review spans, oldest first along first parents, so the page
/// can walk them one at a time or diff any two.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct History {
    /// The commit the review compares against.
    pub base: String,
    pub commits: Vec<Commit>,
    /// The review ends at the working tree, so uncommitted changes follow the last commit.
    pub worktree: bool,
    /// Only the newest commits are listed.
    pub truncated: bool,
}

/// One entry in the page's activity feed.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct ActivityItem {
    pub seq: u64,
    pub at: Millis,
    pub kind: ActivityKind,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToSchema)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum ActivityKind {
    #[serde(rename_all = "camelCase")]
    Opened { notes: u32, collapsed: u32 },
    #[serde(rename_all = "camelCase")]
    UserCommented { thread_id: ThreadId, path: String, line: u32 },
    #[serde(rename_all = "camelCase")]
    AgentReplied { thread_id: ThreadId, path: String, line: u32 },
    #[serde(rename_all = "camelCase")]
    AgentNoted { thread_id: ThreadId, path: String, line: u32 },
    #[serde(rename_all = "camelCase")]
    Revision { revision: Revision, paths: Vec<String> },
    #[serde(rename_all = "camelCase")]
    AgentSaid { message_id: MessageId },
    #[serde(rename_all = "camelCase")]
    Show { request: ShowRequest },
}

impl ActivityKind {
    /// Whether this is something the agent did, which the user hasn't seen yet.
    pub fn from_agent(&self) -> bool {
        matches!(
            self,
            Self::AgentReplied { .. } | Self::AgentNoted { .. } | Self::AgentSaid { .. } | Self::Show { .. } | Self::Revision { .. }
        )
    }
}

#[cfg(test)]
mod export {
    use super::SyntaxClass;

    /// Writes `web/src/gen/syntaxClasses.ts`, the index → name table for
    /// [`SideText::syntax`]. Runs with `just types`.
    #[test]
    #[ignore = "Upstream frontend generator; Macro generates its own review types"]
    fn export_syntax_classes() {
        let names: Vec<String> = SyntaxClass::ALL.iter().map(|c| format!("\"{}\"", c.name())).collect();
        let ts = format!(
            "// Generated by diffd-core (model.rs). Do not edit by hand.\n\n\
             /** Syntax classes by index, as used in `SideText.syntax`. */\n\
             export const SYNTAX_CLASSES = [{}] as const;\n\n\
             export type SyntaxClass = (typeof SYNTAX_CLASSES)[number];\n",
            names.join(", ")
        );
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../web/src/gen/syntaxClasses.ts");
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, ts).unwrap();
    }
}
